import assert from 'node:assert/strict';
import { ToyRoomBattle } from '../../../../src/js/toy-room/ToyRoomBattle.js';
import { beginArenaSpecial, ARENA_SPECIAL } from '../../../../src/js/toy-room/ArenaSpecialAttack.js';
import { arenaDifficulty } from '../../../../src/js/toy-room/ArenaDifficulty.js';
import { sampleArenaPlayerAnimation } from '../../../../src/js/toy-room/ArenaPlayerAnimation.js';
import { ArenaCamera } from '../../../../src/js/toy-room/ArenaCamera.js';
function fixture(difficulty='NORMAL') {
 const room={keysDown:{},gamepadState:{},touchState:{},player:{x:430,facing:'right'},clearInput(){this.player.isMoving=false;},tutorial:{},
  story:{state:{},attack(){return true;}},furniture:[{id:'toy-chest'}]};
 const battle=new ToyRoomBattle(room,{loadAssets:false}),profile=arenaDifficulty(difficulty);
 battle.presentation={enemies:profile.enemies};battle.tuning=profile.tuning;
 battle.activate();battle.state.transition=null;return battle;
}
let count=0;
for(const difficulty of ['NORMAL','EASY'])for(const actor of ['train','robot','dinosaur','bear'])for(const direction of [-1,1])for(const dt of [.5,1,2.4,12]) {
 const b=fixture(difficulty),s=b.state;s.index=['train','robot','dinosaur','bear'].indexOf(actor);b.spawn();s.transition=null;
 s.enemy.x=direction>0?1250:200;b.room.player.x=direction>0?300:1300;
 s.enemy.state='ATTACK';s.enemy.attack=actor==='bear'?'Toy Leap':'Front Charge';s.enemy.elapsed=60;
 s.jump=70;s.jumpVelocity=3;s.player.hp=2;
 const before={x:b.room.player.x,enemyX:s.enemy.x,enemyElapsed:s.enemy.elapsed,jump:s.jump};
 assert.equal(beginArenaSpecial(b),true);assert.equal(beginArenaSpecial(b),false);assert.equal(b.attack(),false);
 while(s.specialAttack.elapsed<ARENA_SPECIAL.launch)b.update(Math.min(dt,ARENA_SPECIAL.launch-s.specialAttack.elapsed));
 assert.equal(s.enemy.hp,s.enemy.maxHp);assert.equal(s.enemy.elapsed,before.enemyElapsed);
 assert.equal(s.jump,before.jump);assert.equal(b.room.player.x,before.x);assert.equal(s.enemy.x,before.enemyX);
 assert.equal(sampleArenaPlayerAnimation(s,b.room.player).facing,direction);
 const restored=fixture(difficulty);restored.restore(b.snapshot());restored.room.player={...b.room.player};
 assert.equal(beginArenaSpecial(restored),false);
 for(const target of [b,restored]) {
  while(target.state.specialAttack)target.update(dt);
  assert.equal(target.state.enemy.hp,actor==='bear'?1:0);
  assert.equal(target.state.player.hp,2,'Sem transferência de corações não solicitada');
  assert.equal(target.state.history.filter(e=>e.event==='SPECIAL_HIT').length,1);
  assert.equal(beginArenaSpecial(target),false);
  target.spawn();target.state.transition=null;assert.equal(beginArenaSpecial(target),false,'Troca de inimigo preserva consumo');
 }
 count++;
}
const b=fixture();b.state.enemy.actor='bear';b.state.enemy.hp=1;
assert.equal(beginArenaSpecial(b),true);while(b.state.specialAttack)b.update(12);assert.equal(b.state.enemy.hp,1);
for(const reason of ['transition','defeat','death','damage','attack','used']) {
 const b=fixture();if(reason==='transition')b.state.transition={elapsed:0};
 if(reason==='defeat')b.state.mode='DEFEAT';if(reason==='death')b.state.enemy.hp=0;
 if(reason==='damage')b.state.playerHitTime=10;if(reason==='attack')b.state.attackTime=10;if(reason==='used')b.state.specialUsed=true;
 assert.equal(beginArenaSpecial(b),false,reason);
}
const camera=new ArenaCamera(),layout={safeLeft:0,safeRight:1440,safeTop:0,safeBottom:900,scale:1,usableWidth:1440,usableHeight:900};
const c=fixture();beginArenaSpecial(c);const normal=camera.frame(layout,c.room,{...c.state,specialAttack:null});
c.state.specialAttack.elapsed=60;const close=camera.frame(layout,c.room,c.state);assert.ok(close.scale>normal.scale*2);
assert.ok(Math.abs((c.room.player.x+19)*close.scale+close.ox-720)<1);
c.state.specialAttack.elapsed=88;assert.deepEqual(camera.frame(layout,c.room,c.state),normal);
const legacy=fixture();legacy.restore({...legacy.snapshot(),specialUsed:undefined,specialAttack:undefined});assert.equal(beginArenaSpecial(legacy),true);
console.log(`APROVADO: ${count} cenários em NORMAL/EASY, ambos os lados, dt variável, suspensão, dano, save durante disparo, uso único, bloqueios e câmera.`);
